const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];

// Subtle admin background motion — pointer + scroll responsive, independent of public-site JS.
(function initAdminAmbientMotion(){
  const bg=document.querySelector('.admin-ambient'); if(!bg) return;
  if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  const grid=bg.querySelector('.ambient-grid'), a=bg.querySelector('.orb-a'), b=bg.querySelector('.orb-b');
  let mx=0,my=0,scrollY=0;
  window.addEventListener('pointermove',e=>{mx=(e.clientX/innerWidth-.5);my=(e.clientY/innerHeight-.5)},{passive:true});
  window.addEventListener('scroll',()=>{scrollY=window.scrollY||0},{passive:true});
  const tick=()=>{
    const sy=Math.min(scrollY/1800,1);
    if(grid) grid.style.transform=`perspective(900px) rotateX(58deg) translateY(calc(18% + ${sy*6}%)) translateX(${mx*-45 + sy*-35}px)`;
    if(a) a.style.transform=`translate3d(${mx*-2.2}vw,${my*-2.2 + sy*1.5}vh,0) scale(${1.01+sy*.03})`;
    if(b) b.style.transform=`translate3d(${mx*2}vw,${my*1.8 - sy*1.5}vh,0) scale(${.99+sy*.015})`;
    requestAnimationFrame(tick);
  };
  tick();
})();
let projects=[],brands=[],contentItems=[],gallery=[];
const msg=(el,text,ok=false)=>{if(!el)return;el.className=ok?'success':'error';el.textContent=text};
async function api(path,opt={}){const headers={...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opt.headers||{})};const r=await fetch('/api'+path,{credentials:'include',cache:'no-store',...opt,headers});let d={};try{d=await r.json()}catch{}if(!r.ok){const e=d?.error;const detail=typeof e==='string'?e:(e?.fieldErrors?Object.entries(e.fieldErrors).flatMap(([k,v])=>[`${k}: ${Array.isArray(v)?v.join(', '):String(v)}`]).join(' · '):e?.formErrors?.join?.(' · ')||JSON.stringify(e)||'Request failed');throw new Error(detail)}return d}
async function uploadImage(file){if(!file)return null;const max=25*1024*1024;if(file.size>max)throw new Error('Image is larger than 25 MB.');const r=await fetch('/api/admin/media/upload',{method:'POST',credentials:'include',headers:{'Content-Type':file.type,'X-Filename':file.name},body:file});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Image upload failed');return d}
async function uploadSheet(file,kind){if(!file)throw new Error('Choose a CSV/XLS/XLSX file first.');const max=20*1024*1024;if(file.size>max)throw new Error('Sheet is larger than 20 MB.');const r=await fetch('/api/admin/import/'+kind,{method:'POST',credentials:'include',headers:{'Content-Type':file.type||'application/octet-stream','X-Filename':file.name},body:file});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Sheet import failed');return d}
async function importGoogleSheet(url,kind){const d=await api('/admin/import/'+kind,{method:'POST',body:JSON.stringify({googleSheetUrl:url})});return d}
async function boot(){try{await api('/auth/me');$('#loginPanel').classList.add('hidden');$('#cms').classList.remove('hidden');await load();return true}catch(e){return false}}
async function load(){try{const [p,b,c]=await Promise.all([api('/admin/projects'),api('/admin/brands'),api('/admin/content')]);projects=p.projects;brands=b.brands;contentItems=c.content;renderProjects();renderBrands();renderContent();renderImportStats();loadDashboard().catch(()=>{})}catch(e){$('#cms').insertAdjacentHTML('afterbegin',`<div class="panel error" style="margin-bottom:20px">CMS data could not be loaded: ${esc(e.message)}</div>`);throw e}}
function showToast(text,ok=true){const t=$('#toast');if(!t)return;t.textContent=text;t.className='toast '+(ok?'success':'error')+' show';clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
function setLoading(on,text='WORKING…'){const el=$('#adminLoading');if(!el)return;$('#adminLoadingText').textContent=text;el.classList.toggle('show',!!on)}
function statusPill(v){const x=String(v||'').toUpperCase();const cls=x==='PUBLISHED'||x==='PUBLIC'?'live':(x==='PRIVATE'||x==='ARCHIVED'?'private':'draft');return `<span class="status-pill ${cls}">${esc(x||'—')}</span>`}
async function loadDashboard(){try{const [st,act,iq]=await Promise.all([api('/admin/maintenance/status'),api('/admin/maintenance/activity'),api('/admin/maintenance/inquiries')]);const c=st.counts||{};const published=projects.filter(x=>x.status==='PUBLISHED').length;const drafts=projects.filter(x=>x.status==='DRAFT').length;const newIq=(iq.inquiries||[]).filter(x=>String(x.status||'').toUpperCase()==='NEW').length;$('#dashProjects').textContent=c.projects??projects.length;$('#dashPublished').textContent=published;$('#dashDrafts').textContent=drafts;$('#dashContent').textContent=c.content??contentItems.length;$('#dashInquiries').textContent=newIq;const h=$('#dashboardHealth');if(h)h.innerHTML=`<span class="dot ${st.database?'':'bad'}"></span> ${st.database?'SYSTEM HEALTHY':'DATABASE CHECK FAILED'}`;const ss=$('#dashboardStatus');if(ss)ss.innerHTML=`<div><strong>${st.database?'OK':'ERR'}</strong><span>DATABASE</span></div><div><strong>${esc(String(st.storage||'—').toUpperCase())}</strong><span>STORAGE</span></div>`;const recentProjects=projects.slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt||0)-new Date(a.updatedAt||a.createdAt||0)).slice(0,5);const work=$('#dashboardProjects');if(work)work.innerHTML=recentProjects.map(p=>`<div class="dash-row dashboard-project-row"><div><strong>${esc(p.title)}</strong><small>${esc(p.category||'PROJECT')} · ${esc(p.status||'DRAFT')} · ${esc(p.visibility||'PUBLIC')}</small></div><button type="button" class="admin-btn" data-dashboard-project="${esc(p.id)}">EDIT</button></div>`).join('')||'<p class="notice">No projects yet.</p>';work?.querySelectorAll('[data-dashboard-project]').forEach(b=>b.addEventListener('click',()=>editProject(b.dataset.dashboardProject)));const list=$('#dashboardActivity');if(list){const rows=(act.activity||[]).slice(0,8);list.innerHTML=rows.map(x=>`<div class="dash-row"><div><strong>${esc(x.label||x.action||'Activity')}</strong><small>${esc(x.entity||'SYSTEM')} · ${new Date(x.createdAt).toLocaleString()}</small></div>${statusPill(x.action)}</div>`).join('')||'<p class="notice">No activity recorded yet.</p>'}}catch(e){const h=$('#dashboardHealth');if(h)h.innerHTML='<span class="dot bad"></span> SYSTEM CHECK FAILED';const list=$('#dashboardActivity');if(list)list.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
function openAdminTab(name){$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));['dashboard','projects','content','brands','imports','maintenance','account'].forEach(k=>{const el=$('#'+k+'Tab');if(el)el.classList.toggle('hidden',name!==k)});if(name==='dashboard')loadDashboard();if(name==='account')loadAccount();if(name==='maintenance'){switchMaintenancePanel('overview');loadMaintenance()}}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function isoToLocal(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function localToIso(v){return v?new Date(v).toISOString():null}
function fillProject(p){
  if(!p)return;
  $('#pid').value=p.id||'';
  $('#title').value=p.title||'';
  $('#slug').value=p.slug||'';
  $('#category').value=p.category||'Amazon / E-commerce';
  $('#service').value=p.service||'';
  $('#type').value=p.type||'';
  $('#client').value=p.client||'';
  $('#year').value=p.year??'';
  $('#coverImage').value=p.coverImage||'';
  $('#description').value=p.description||'';
  $('#challenge').value=p.challenge||'';
  $('#approach').value=p.approach||'';
  $('#process').value=p.process||'';
  $('#results').value=p.results||'';
  $('#deliverables').value=Array.isArray(p.deliverables)?p.deliverables.join('\n'):(p.deliverables||'');
  $('#tools').value=Array.isArray(p.tools)?p.tools.join('\n'):(p.tools||'');
  $('#role').value=p.role||'';
  $('#sortOrder').value=p.sortOrder??0;
  $('#clientExpiresAt').value=isoToLocal(p.clientExpiresAt);
  $('#scheduledAt').value=isoToLocal(p.scheduledAt);
  $('#seoTitle').value=p.seoTitle||'';
  $('#seoDescription').value=p.seoDescription||'';
  $('#liveUrl').value=p.liveUrl||'';
  $('#status').value=p.status||'DRAFT';
  $('#visibility').value=p.visibility||'PUBLIC';
  $('#featured').checked=!!p.featured;
  $('#sliderEnabled').checked=p.sliderEnabled!==false;
  $('#sliderTransition').value=p.sliderTransition||'AUTO';
  $('#clientOnly').checked=!!p.clientOnly;
  gallery=Array.isArray(p.gallery)?p.gallery.map((g,i)=>typeof g==='string'?{url:g,alt:p.title||'',sortOrder:i}:({...g,sortOrder:g.sortOrder??i})):[];
  $('#projectHeading').textContent='Edit project';
  $('#uploadMsg').textContent='';
  renderGallery();
  updateProjectSeoPreview();
}
function renderProjects(){const el=$('#projectList');const q=($('#projectSearch')?.value||'').trim().toLowerCase();const filtered=projects.filter(p=>!q||[p.title,p.client,p.category,p.service,p.type,p.status,p.visibility].some(v=>String(v||'').toLowerCase().includes(q)));const count=$('#projectResultCount');if(count)count.textContent=`${filtered.length} / ${projects.length}`;el.innerHTML=filtered.map(p=>`<div class="project-item"><img src="${esc(p.coverImage||'assets/amazon-01.svg')}" alt=""><div><strong>${esc(p.title)}</strong><small>${esc(p.category)} · ${esc(p.status)} · ${esc(p.visibility)}${p.featured?' · FEATURED':''}${p.sliderEnabled!==false?' · SLIDER ON':' · SLIDER OFF'}${p.sliderTransition&&p.sliderTransition!=='AUTO'?' · '+esc(p.sliderTransition):''}${p.clientOnly?' · CLIENT ONLY':''}</small></div><div class="item-actions"><button type="button" class="admin-btn js-edit" data-id="${esc(p.id)}">EDIT</button><button type="button" class="admin-btn js-share" data-id="${esc(p.id)}">SHARE</button>${p.accessTokenHash?'<button type="button" class="admin-btn js-revoke" data-id="'+esc(p.id)+'">REVOKE</button>':''}<button type="button" class="admin-btn danger js-delete" data-id="${esc(p.id)}">DELETE</button></div></div>`).join('')||'<p class="notice">No projects match your search.</p>';el.querySelectorAll('.js-edit').forEach(b=>b.addEventListener('click',()=>editProject(b.dataset.id)));el.querySelectorAll('.js-share').forEach(b=>b.addEventListener('click',()=>shareProject(b.dataset.id)));el.querySelectorAll('.js-revoke').forEach(b=>b.addEventListener('click',()=>revokeShare(b.dataset.id)));el.querySelectorAll('.js-delete').forEach(b=>b.addEventListener('click',()=>deleteProject(b.dataset.id)))}
function renderBrands(){const el=$('#brandList');el.innerHTML=brands.map(b=>`<div class="project-item"><img src="${esc(b.logoAsset||'assets/branding-01.svg')}" alt=""><div><strong>${esc(b.name)}</strong><small>${b.active?'ACTIVE':'HIDDEN'} · ORDER ${esc(b.sortOrder)}</small></div><div><button type="button" class="admin-btn js-edit-brand" data-id="${esc(b.id)}">EDIT</button><button type="button" class="admin-btn danger js-delete-brand" data-id="${esc(b.id)}">DELETE</button></div></div>`).join('')||'<p class="notice">No brands yet.</p>';el.querySelectorAll('.js-edit-brand').forEach(b=>b.addEventListener('click',()=>editBrand(b.dataset.id)));el.querySelectorAll('.js-delete-brand').forEach(b=>b.addEventListener('click',()=>deleteBrand(b.dataset.id)))}
function renderImportStats(){const p=$('#projectCount');const c=$('#contentCount');if(p)p.textContent=projects.length;if(c)c.textContent=contentItems.length}
function renderGallery(){const el=$('#galleryPreview');el.innerHTML=gallery.length?gallery.map((g,i)=>`<div class="upload-thumb"><img src="${esc(g.url)}" alt=""><button type="button" class="admin-btn danger" data-gallery-remove="${i}">REMOVE</button></div>`).join(''):'<span class="notice">No gallery images added.</span>';el.querySelectorAll('[data-gallery-remove]').forEach(b=>b.addEventListener('click',()=>{gallery.splice(Number(b.dataset.galleryRemove),1);renderGallery()}))}
function seoRangeStatus(titleLen,descLen){const title=titleLen>=50&&titleLen<=60;const desc=descLen>=140&&descLen<=160;if(title&&desc)return 'GOOD RANGE';if(titleLen===0&&descLen===0)return 'READY';return title||desc?'PARTIAL RANGE':'CHECK LENGTH'}
function updateProjectSeoPreview(){const title=$('#seoTitle')?.value.trim()||$('#title')?.value.trim()||'Project title';const desc=$('#seoDescription')?.value.trim()||'Your SEO description will appear here.';const slug=$('#slug')?.value.trim()||'project';if($('#projectSeoPreviewTitle'))$('#projectSeoPreviewTitle').textContent=title;if($('#projectSeoPreviewDescription'))$('#projectSeoPreviewDescription').textContent=desc;if($('#projectSeoUrl'))$('#projectSeoUrl').textContent=(location.host||'yourdomain.com')+'/work/'+slug;if($('#projectSeoTitleCount'))$('#projectSeoTitleCount').textContent=title.length;if($('#projectSeoDescriptionCount'))$('#projectSeoDescriptionCount').textContent=desc.length;if($('#projectSeoStatus'))$('#projectSeoStatus').textContent=seoRangeStatus(title.length,desc.length)}
function updateContentSeoPreview(){const title=$('#contentSeoTitle')?.value.trim()||$('#contentTitle')?.value.trim()||'Article title';const desc=$('#contentSeoDescription')?.value.trim()||'Your SEO description will appear here.';const slug=$('#contentSlug')?.value.trim()||'article';if($('#contentSeoPreviewTitle'))$('#contentSeoPreviewTitle').textContent=title;if($('#contentSeoPreviewDescription'))$('#contentSeoPreviewDescription').textContent=desc;if($('#contentSeoUrl'))$('#contentSeoUrl').textContent=(location.host||'yourdomain.com')+'/journal/'+slug;if($('#contentSeoTitleCount'))$('#contentSeoTitleCount').textContent=title.length;if($('#contentSeoDescriptionCount'))$('#contentSeoDescriptionCount').textContent=desc.length;if($('#contentSeoStatus'))$('#contentSeoStatus').textContent=seoRangeStatus(title.length,desc.length)}
function updateSiteSeoPreview(){const title=$('#settingMetaTitle')?.value.trim()||'Mahmudul Hassan — Creative Designer';const desc=$('#settingMetaDescription')?.value.trim()||'Creative designer specializing in Amazon A+ and e-commerce experiences.';const og=$('#settingOgImage')?.value.trim();const host=location.host||'yourdomain.com';if($('#siteSeoPreviewTitle'))$('#siteSeoPreviewTitle').textContent=title;if($('#siteSeoPreviewDescription'))$('#siteSeoPreviewDescription').textContent=desc;if($('#siteSeoUrl'))$('#siteSeoUrl').textContent=host;if($('#siteOgPreviewTitle'))$('#siteOgPreviewTitle').textContent=title;if($('#siteOgPreviewDescription'))$('#siteOgPreviewDescription').textContent=desc;if($('#siteOgPreviewDomain'))$('#siteOgPreviewDomain').textContent=host;if($('#siteSeoTitleCount'))$('#siteSeoTitleCount').textContent=title.length;if($('#siteSeoDescriptionCount'))$('#siteSeoDescriptionCount').textContent=desc.length;const status=$('#siteSeoStatus');if(status)status.textContent=seoRangeStatus(title.length,desc.length);const img=$('#siteOgPreviewImage');if(img){img.style.backgroundImage=og?`url("${og.replace(/"/g,'')}")`:'';img.classList.toggle('has-image',!!og)}}
window.editProject=id=>{const p=projects.find(p=>p.id===id);if(!p)return;fillProject(p);$('#projectForm').scrollIntoView({behavior:'smooth',block:'start'})};
window.deleteProject=async id=>{if(!confirm('Delete this project? This cannot be undone.'))return;try{await api('/admin/projects/'+id,{method:'DELETE'});await load();msg($('#projectMsg'),'Project deleted.',true)}catch(e){alert(e.message)}};
window.shareProject=async id=>{try{const d=await api('/admin/projects/'+id+'/share-link',{method:'POST'});try{await navigator.clipboard.writeText(d.url)}catch{};prompt('Client share link — copy this URL:',d.url);await load()}catch(e){alert(e.message)}};
window.revokeShare=async id=>{if(!confirm('Revoke this client share link?'))return;try{await api('/admin/projects/'+id+'/share-link',{method:'DELETE'});await load()}catch(e){alert(e.message)}};
$('#coverUpload').addEventListener('change',async()=>{const f=$('#coverUpload').files[0];if(!f)return;try{msg($('#uploadMsg'),'Uploading cover image...',true);const d=await uploadImage(f);$('#coverImage').value=d.publicUrl;msg($('#uploadMsg'),`Cover uploaded via ${d.provider}. Save the project.`,true)}catch(e){msg($('#uploadMsg'),e.message)}});
$('#settingHeroImageUpload')?.addEventListener('change',async()=>{const f=$('#settingHeroImageUpload').files[0];if(!f)return;try{msg($('#heroImageUploadMsg'),'Uploading hero image...',true);const d=await uploadImage(f);$('#settingHeroImage').value=d.publicUrl;const p=$('#heroImagePreview');if(p)p.innerHTML=`<img src="${esc(d.publicUrl)}" alt="Hero preview">`;msg($('#heroImageUploadMsg'),`Hero image uploaded via ${d.provider}. Click SAVE SETTINGS.`,true)}catch(e){msg($('#heroImageUploadMsg'),e.message)}});
$('#galleryUpload').addEventListener('change',async()=>{const files=[...$('#galleryUpload').files];if(!files.length)return;try{msg($('#uploadMsg'),`Uploading ${files.length} gallery image(s)...`,true);for(const f of files){const d=await uploadImage(f);gallery.push({url:d.publicUrl,alt:$('#title').value||f.name,width:null,height:null,sortOrder:gallery.length})}renderGallery();msg($('#uploadMsg'),'Gallery uploaded. Save the project to keep the images.',true);$('#galleryUpload').value=''}catch(e){msg($('#uploadMsg'),e.message)}});
$('#projectForm').onsubmit=async e=>{e.preventDefault();const payload={title:$('#title').value,slug:$('#slug').value,category:$('#category').value,service:$('#service').value||null,type:$('#type').value||null,client:$('#client').value||null,year:$('#year').value?Number($('#year').value):null,role:$('#role').value||null,coverImage:$('#coverImage').value||null,gallery,description:$('#description').value||null,challenge:$('#challenge').value||null,approach:$('#approach').value||null,process:$('#process').value||null,results:$('#results').value||null,deliverables:$('#deliverables').value.split('\n').map(x=>x.trim()).filter(Boolean),tools:$('#tools').value.split('\n').map(x=>x.trim()).filter(Boolean),featured:$('#featured').checked,sliderEnabled:$('#sliderEnabled').checked,sliderTransition:$('#sliderTransition').value||'AUTO',sortOrder:Number($('#sortOrder').value||0),status:$('#status').value,visibility:$('#visibility').value,clientOnly:$('#clientOnly').checked,clientExpiresAt:localToIso($('#clientExpiresAt').value),scheduledAt:localToIso($('#scheduledAt').value),seoTitle:$('#seoTitle').value||null,seoDescription:$('#seoDescription').value||null,liveUrl:$('#liveUrl').value||null};try{if($('#pid').value)await api('/admin/projects/'+$('#pid').value,{method:'PATCH',body:JSON.stringify(payload)});else await api('/admin/projects',{method:'POST',body:JSON.stringify(payload)});msg($('#projectMsg'),'Saved and synced to the public site.',true);$('#clearProject').click();await load()}catch(e){msg($('#projectMsg'),e.message)}};
$('#clearProject').onclick=()=>{$('#projectForm').reset();$('#pid').value='';gallery=[];renderGallery();$('#year').value=new Date().getFullYear();$('#sortOrder').value=0;$('#sliderEnabled').checked=true;$('#sliderTransition').value='AUTO';$('#projectHeading').textContent='Add project';$('#uploadMsg').textContent='';updateProjectSeoPreview()};
async function loadAccount(){try{const d=await api('/auth/me');const u=d.user||{};$('#accountEmail').textContent=u.email||'—';$('#accountRole').textContent=String(u.role||'ADMIN').toUpperCase();$('#accountRoleNote').textContent=String(u.role||'ADMIN').toUpperCase()+' access';$('#accountSessionStatus').textContent='ACTIVE'}catch(e){$('#accountEmail').textContent='Session unavailable';$('#accountSessionStatus').textContent='EXPIRED'}}
$('#passwordForm')?.addEventListener('submit',async e=>{e.preventDefault();const current=$('#currentPassword').value,newPass=$('#newPassword').value,confirmPass=$('#confirmPassword').value;if(newPass!==confirmPass){msg($('#passwordMsg'),'New passwords do not match.');return}if(newPass.length<8){msg($('#passwordMsg'),'New password must be at least 8 characters.');return}try{await api('/auth/password',{method:'POST',body:JSON.stringify({currentPassword:current,newPassword:newPass})});e.target.reset();msg($('#passwordMsg'),'Password updated successfully.',true)}catch(err){msg($('#passwordMsg'),err.message)}});
$('#accountLogout')?.addEventListener('click',()=>$('#logout')?.click());
window.editBrand=id=>{const b=brands.find(x=>x.id===id);if(!b)return;$('#bid').value=b.id;$('#brandName').value=b.name;$('#brandLogo').value=b.logoAsset||'';$('#brandUrl').value=b.url||'';$('#brandOrder').value=b.sortOrder;$('#brandActive').checked=b.active};
window.deleteBrand=async id=>{if(!confirm('Delete this brand?'))return;try{await api('/admin/brands/'+id,{method:'DELETE'});await load()}catch(e){alert(e.message)}};
$('#brandLogoUpload').addEventListener('change',async()=>{const f=$('#brandLogoUpload').files[0];if(!f)return;try{msg($('#brandMsg'),'Uploading logo...',true);const d=await uploadImage(f);$('#brandLogo').value=d.publicUrl;msg($('#brandMsg'),'Logo uploaded. Save the brand.',true)}catch(e){msg($('#brandMsg'),e.message)}});
$('#brandForm').onsubmit=async e=>{e.preventDefault();const p={name:$('#brandName').value,logoAsset:$('#brandLogo').value||null,url:$('#brandUrl').value||null,sortOrder:Number($('#brandOrder').value||0),active:$('#brandActive').checked};try{if($('#bid').value)await api('/admin/brands/'+$('#bid').value,{method:'PATCH',body:JSON.stringify(p)});else await api('/admin/brands',{method:'POST',body:JSON.stringify(p)});msg($('#brandMsg'),'Saved and synced.',true);$('#clearBrand').click();await load()}catch(e){msg($('#brandMsg'),e.message)}};
$('#clearBrand').onclick=()=>{$('#brandForm').reset();$('#bid').value='';$('#brandActive').checked=true;$('#brandOrder').value=0};
$('#seoTitle')?.addEventListener('input',updateProjectSeoPreview);$('#seoDescription')?.addEventListener('input',updateProjectSeoPreview);$('#title')?.addEventListener('input',updateProjectSeoPreview);$('#slug')?.addEventListener('input',updateProjectSeoPreview);$('#contentSeoTitle')?.addEventListener('input',updateContentSeoPreview);$('#contentSeoDescription')?.addEventListener('input',updateContentSeoPreview);$('#contentTitle')?.addEventListener('input',updateContentSeoPreview);$('#contentSlug')?.addEventListener('input',updateContentSeoPreview);$('#settingMetaTitle')?.addEventListener('input',updateSiteSeoPreview);$('#settingMetaDescription')?.addEventListener('input',updateSiteSeoPreview);$('#settingOgImage')?.addEventListener('input',updateSiteSeoPreview);
function setEditorPreview(){const body=$('#contentBody').value||'';const preview=$('#contentPreview');if(!preview)return;let h=esc(body);h=h.replace(/!\[([^\]]*)\]\(((?:https?:\/\/|\/)[^)]+)\)/g,'<figure class="editor-inline-image"><img src="$2" alt="$1"><figcaption>$1</figcaption></figure>');h=h.replace(/^### (.*)$/gm,'<h4>$1</h4>').replace(/^## (.*)$/gm,'<h3>$1</h3>').replace(/^# (.*)$/gm,'<h2>$1</h2>').replace(/^> (.*)$/gm,'<blockquote>$1</blockquote>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>').replace(/\[(.*?)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>');h=h.replace(/(?:^|\n)((?:[-*] .+(?:\n|$))+)/g,(m)=>'<ul>'+m.trim().split(/\n/).map(x=>'<li>'+x.replace(/^[-*] /,'')+'</li>').join('')+'</ul>');h=h.replace(/(?:^|\n)((?:\d+\. .+(?:\n|$))+)/g,(m)=>'<ol>'+m.trim().split(/\n/).map(x=>'<li>'+x.replace(/^\d+\. /,'')+'</li>').join('')+'</ol>');h=h.replace(/\n\n+/g,'</p><p>').replace(/\n/g,'<br>');preview.innerHTML='<p>'+h+'</p>'}
function insertMarkdown(prefix,suffix=''){const ta=$('#contentBody');if(!ta)return;const a=ta.selectionStart,b=ta.selectionEnd,v=ta.value;const selected=v.slice(a,b)||'text';ta.value=v.slice(0,a)+prefix+selected+suffix+v.slice(b);ta.focus();ta.setSelectionRange(a+prefix.length,a+prefix.length+selected.length);setEditorPreview()}
function insertList(ordered=false){const ta=$('#contentBody');if(!ta)return;const a=ta.selectionStart,b=ta.selectionEnd,v=ta.value;const selected=v.slice(a,b)||'List item';const lines=selected.split('\n').map((line,i)=>`${ordered?i+1+'.':'-'} ${line.replace(/^[-*] |^\d+\. /,'')}`);const text=lines.join('\n');ta.value=v.slice(0,a)+text+v.slice(b);ta.focus();ta.setSelectionRange(a,a+text.length);setEditorPreview()}
$$('[data-md]').forEach(b=>b.addEventListener('click',()=>{const x=b.dataset.md;if(x==='h2')insertMarkdown('## ','');if(x==='bold')insertMarkdown('**','**');if(x==='italic')insertMarkdown('*','*');if(x==='link')insertMarkdown('[','](https://)');if(x==='ul')insertList(false);if(x==='ol')insertList(true);if(x==='quote')insertMarkdown('> ','')}));$('#contentBody')?.addEventListener('input',setEditorPreview);

async function fillContent(cOrId, slug){let c=typeof cOrId==='object'&&cOrId?cOrId:null;let recordId=String(c?.id||cOrId||'').trim();if(recordId==='undefined'||recordId==='null')recordId='';let recordSlug=String(c?.slug||slug||'').trim();if((!recordId||recordId==='')&&recordSlug){try{const d=await api('/admin/content/by-slug/'+encodeURIComponent(recordSlug));c=d?.content||null;recordId=String(c?.id||'').trim()}catch(e){msg($('#contentMsg'),e.message,false);return}}if(!recordId&&recordSlug){try{const d=await api('/admin/content/by-slug/'+encodeURIComponent(recordSlug));c=d?.content||null;recordId=String(c?.id||'').trim()}catch(e){msg($('#contentMsg'),e.message,false);return}}if(!recordId){msg($('#contentMsg'),'This content record could not be resolved. The CMS has no usable ID or slug for this item.',false);return;}if(!c){try{const d=await api('/admin/content/'+encodeURIComponent(recordId));c=d?.content||null}catch(e){msg($('#contentMsg'),e.message,false);return}}if(!c){msg($('#contentMsg'),'Content record could not be loaded.',false);return;}$('#cid').value=recordId;$('#contentTitle').value=c.title;$('#contentSlug').value=c.slug;$('#contentType').value=c.type||'BLOG';$('#contentCategory').value=c.category||'';$('#contentExcerpt').value=c.excerpt||'';$('#contentBody').value=c.body||'';$('#contentCover').value=c.coverImage||'';$('#contentTags').value=(c.tags||[]).join(', ');$('#contentAuthor').value=c.author||'';$('#contentSeoTitle').value=c.seoTitle||'';$('#contentSeoDescription').value=c.seoDescription||'';$('#contentStatus').value=c.status;$('#contentScheduledAt').value=isoToLocal(c.scheduledAt);$('#contentFeatured').checked=!!c.featured;$('#contentOrder').value=c.sortOrder||0;setEditorPreview();$('#contentHeading').textContent='Edit content';document.querySelector('[data-tab="content"]').click();$('#contentForm').scrollIntoView({behavior:'smooth',block:'start'})}
window.editContent=fillContent;
window.deleteContent=async(id,slug)=>{if(!confirm('Delete this content?'))return;let recordId=String(id||'').trim();if((!recordId||recordId==='undefined'||recordId==='null')&&slug){try{const d=await api('/admin/content/by-slug/'+encodeURIComponent(slug));recordId=String(d?.content?.id||'').trim()}catch(e){alert(e.message);return}}if(!recordId){alert('This content cannot be deleted because its database record could not be resolved.');return}try{await api('/admin/content/'+encodeURIComponent(recordId),{method:'DELETE'});await load()}catch(e){alert(e.message)}};
$('#contentCoverUpload')?.addEventListener('change',async()=>{const f=$('#contentCoverUpload').files[0];if(!f)return;try{msg($('#contentUploadMsg'),'Uploading cover image...',true);const d=await uploadImage(f);$('#contentCover').value=d.publicUrl;msg($('#contentUploadMsg'),'Cover uploaded. Save content.',true)}catch(e){msg($('#contentUploadMsg'),e.message)}});
$('#insertContentImage')?.addEventListener('click',()=>$('#contentInlineImageUpload')?.click());$('#contentInlineImageUpload')?.addEventListener('change',async()=>{const f=$('#contentInlineImageUpload').files[0];if(!f)return;try{msg($('#contentImageMsg'),'Uploading inline image...',true);const ta=$('#contentBody');const cursor=ta.selectionStart||ta.value.length;const d=await uploadImage(f);const alt=(f.name||'Content image').replace(/\.[^.]+$/,'').replace(/[-_]+/g,' ');const md=`![${alt}](${d.publicUrl})`;ta.value=ta.value.slice(0,cursor)+md+ta.value.slice(cursor);ta.focus();ta.setSelectionRange(cursor+md.length,cursor+md.length);setEditorPreview();msg($('#contentImageMsg'),`Image inserted via ${d.provider}. Save the content to keep it.`,true)}catch(e){msg($('#contentImageMsg'),e.message)}finally{$('#contentInlineImageUpload').value=''}});
$('#contentTitle')?.addEventListener('input',()=>{const slugEl=$('#contentSlug');if(!$('#cid').value.trim()&&slugEl&&!slugEl.dataset.edited){slugEl.value=$('#contentTitle').value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120)}});
$('#contentSlug')?.addEventListener('input',()=>{$('#contentSlug').dataset.edited='1'});
$('#contentForm')?.addEventListener('submit',async e=>{e.preventDefault();const title=$('#contentTitle').value.trim();const slug=$('#contentSlug').value.trim();if(!title){msg($('#contentMsg'),'Title is required.');return}if(!slug){msg($('#contentMsg'),'Slug is required.');return}const payload={title,slug,type:$('#contentType').value,category:$('#contentCategory').value||null,excerpt:$('#contentExcerpt').value||null,body:$('#contentBody').value,coverImage:$('#contentCover').value||null,gallery:[],tags:$('#contentTags').value.split(',').map(x=>x.trim()).filter(Boolean),author:$('#contentAuthor').value||null,seoTitle:$('#contentSeoTitle').value||null,seoDescription:$('#contentSeoDescription').value||null,status:$('#contentStatus').value,scheduledAt:localToIso($('#contentScheduledAt').value),featured:$('#contentFeatured').checked,sortOrder:Number($('#contentOrder').value||0)};try{const rawId=$('#cid').value.trim();const id=rawId&&rawId!=='undefined'&&rawId!=='null'?rawId:'';if(id)await api('/admin/content/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify(payload)});else await api('/admin/content',{method:'POST',body:JSON.stringify(payload)});msg($('#contentMsg'),'Content saved.',true);$('#clearContent').click();await load()}catch(e){msg($('#contentMsg'),e.message)}});
$('#clearContent')?.addEventListener('click',()=>{$('#contentForm').reset();$('#cid').value='';$('#contentStatus').value='DRAFT';$('#contentOrder').value=0;$('#contentHeading').textContent='Write content';$('#contentUploadMsg').textContent='';setEditorPreview()});
async function runSheetImport(kind){const fileId=kind==='projects'?'#projectSheet':'#contentSheet';const urlId=kind==='projects'?'#projectSheetUrl':'#contentSheetUrl';const resultId=kind==='projects'?'#projectImportResult':'#contentImportResult';try{let preview;if($(fileId).files[0]){const f=$(fileId).files[0];const max=20*1024*1024;if(f.size>max)throw new Error('Sheet is larger than 20 MB.');const r=await fetch('/api/admin/import/'+kind+'/preview',{method:'POST',credentials:'include',headers:{'Content-Type':f.type||'application/octet-stream','X-Filename':f.name},body:f});preview=await r.json();if(!r.ok)throw new Error(preview.error||'Could not preview sheet')}else if($(urlId).value.trim()){preview=await api('/admin/import/'+kind+'/preview',{method:'POST',body:JSON.stringify({googleSheetUrl:$(urlId).value.trim()})})}else throw new Error('Choose a sheet file or paste a public Google Sheet URL.');const count=preview.count||0;if(!count)throw new Error('No valid rows found. Check the sheet columns and required fields.');if(!confirm(`Found ${count} valid ${kind} row(s). Import them as DRAFT now?`))return;let d;if($(fileId).files[0])d=await uploadSheet($(fileId).files[0],kind);else d=await importGoogleSheet($(urlId).value.trim(),kind);$(resultId).innerHTML=`<strong>Imported ${d.imported}</strong> · skipped ${d.skipped}. ${d.skippedItems?.length?'Existing slugs were skipped safely.':''}`;await load()}catch(e){$(resultId).textContent=e.message;$(resultId).className='error'}}
$('#projectBatchImport')?.addEventListener('click',()=>runSheetImport('projects'));$('#contentBatchImport')?.addEventListener('click',()=>runSheetImport('content'));
$('#loginForm').onsubmit=async e=>{e.preventDefault();const btn=$('#loginForm button[type=submit]');btn.disabled=true;btn.textContent='SIGNING IN...';msg($('#loginMsg'),'');try{await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value})});const ok=await boot();if(!ok)throw new Error('Login succeeded, but the session could not be verified. Restart the server and try again.');msg($('#loginMsg'),'Signed in successfully.',true)}catch(e){msg($('#loginMsg'),e.message)}finally{btn.disabled=false;btn.textContent='SIGN IN'}};
$('#logout').onclick=async()=>{await api('/auth/logout',{method:'POST'});location.reload()};
