const DEFAULT_SLIDER_SETTINGS={enabled:true,mode:'AUTO_MANUAL',interval:5,pauseHover:true,pauseHidden:true,loop:true,arrows:true,counter:true,progress:false,dots:false,keyboard:true,wheel:false,swipe:true,transitionMode:'RANDOM',fixedTransition:'MASK',duration:900,easing:'SMOOTH',preload:true,randomStart:false,drag:true,clickOpen:true,maxSlides:8,mobileAuto:true,mobileInterval:4,mobileArrows:false,mobileSwipe:true,reducedMotion:true,pauseOffscreen:true,lazy:true};
const DEFAULT_PARTICLE_CONFIG={enabled:true,style:'NEURAL',density:46,speed:.22,linkDistance:150,nodeSize:1,lineOpacity:.16,depth:1,mouseStrength:.35,pulse:.35};
const particleFields={enabled:'particleEnabled',style:'particleStyle',density:'particleDensity',speed:'particleSpeed',linkDistance:'particleLinkDistance',nodeSize:'particleNodeSize',lineOpacity:'particleLineOpacity',depth:'particleDepth',mouseStrength:'particleMouseStrength',pulse:'particlePulse'};
function fillParticleSettings(cfg={}){const x={...DEFAULT_PARTICLE_CONFIG,...(cfg||{})};currentParticleConfig=x;Object.entries(particleFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;if(el.type==='checkbox')el.checked=!!x[k];else el.value=x[k]??''});updateParticleValueLabels()}
function readParticleSettings(){const x={};Object.entries(particleFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;x[k]=el.type==='checkbox'?el.checked:(el.type==='range'?Number(el.value):el.value)});return x}
function updateParticleValueLabels(){const map={particleSpeed:'particleSpeedValue',particleDensity:'particleDensityValue',particleLinkDistance:'particleLinkDistanceValue',particleNodeSize:'particleNodeSizeValue',particleDepth:'particleDepthValue',particleMouseStrength:'particleMouseStrengthValue',particlePulse:'particlePulseValue',particleLineOpacity:'particleLineOpacityValue'};Object.entries(map).forEach(([a,b])=>{const el=$('#'+a),out=$('#'+b);if(el&&out){const v=Number(el.value);out.textContent=(a==='particleDensity'||a==='particleLinkDistance')?String(Math.round(v)):v.toFixed(2)}})}
let currentParticleConfig={};
const sliderFields={enabled:'sliderEnabledGlobal',mode:'sliderMode',interval:'sliderInterval',pauseHover:'sliderPauseHover',pauseHidden:'sliderPauseHidden',loop:'sliderLoop',arrows:'sliderArrows',counter:'sliderCounter',progress:'sliderProgress',dots:'sliderDots',keyboard:'sliderKeyboard',wheel:'sliderWheel',swipe:'sliderSwipe',transitionMode:'sliderTransitionMode',fixedTransition:'sliderFixedTransition',duration:'sliderDuration',easing:'sliderEasing',preload:'sliderPreload',randomStart:'sliderRandomStart',drag:'sliderDrag',clickOpen:'sliderClickOpen',maxSlides:'sliderMaxSlides',mobileAuto:'sliderMobileAuto',mobileInterval:'sliderMobileInterval',mobileArrows:'sliderMobileArrows',mobileSwipe:'sliderMobileSwipe',reducedMotion:'sliderReducedMotion',pauseOffscreen:'sliderPauseOffscreen',lazy:'sliderLazy'};
function fillSliderSettings(cfg={}){const x={...DEFAULT_SLIDER_SETTINGS,...(cfg||{})};currentParticleConfig={...DEFAULT_PARTICLE_CONFIG,...(x.particleConfig||{})};Object.entries(sliderFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;if(el.type==='checkbox')el.checked=!!x[k];else el.value=x[k]??''})}
function readSliderSettings(){const x={};Object.entries(sliderFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;x[k]=el.type==='checkbox'?el.checked:(el.type==='number'?Number(el.value):el.value)});x.particleConfig={...currentParticleConfig};return x}
function switchMaintenancePanel(name){$$('.maintenance-subtab').forEach(b=>b.classList.toggle('active',b.dataset.maintenanceTab===name));['overview','slider','background','skills','site','testimonials','activity','inquiries','reviews'].forEach(k=>$('#maintenance'+k.charAt(0).toUpperCase()+k.slice(1))?.classList.toggle('hidden',k!==name))}
async function loadMaintenance(){try{const [st,settings,t,a,iq,rv]=await Promise.all([api('/admin/maintenance/status'),api('/admin/maintenance/settings'),api('/admin/maintenance/testimonials'),api('/admin/maintenance/activity'),api('/admin/maintenance/inquiries'),api('/admin/maintenance/reviews')]);const vals=[st.database?'OK':'ERROR',st.storage==='configured'?'CONFIGURED':'LOCAL',st.counts.projects,st.counts.content,st.counts.media];$('#systemStatus').innerHTML=vals.map((v,i)=>`<div><strong>${esc(v)}</strong><span>${['DATABASE','STORAGE','PROJECTS','CONTENT','MEDIA'][i]}</span></div>`).join('');const x=settings.settings||{};fillSliderSettings(x.sliderConfig||{});fillParticleSettings(x.sliderConfig?.particleConfig||{});renderSkills(Array.isArray(x.skillsConfig)?x.skillsConfig:[]);['SiteName','Title','Email','InquiryRecipientEmail','InquirySubject','Phone','Location','AvailabilityLabel','Linkedin','Behance','Dribbble','Instagram','Github','MetaTitle','MetaDescription','OgImage','HeroImage','HeroLeadText'].forEach(k=>{const id='#setting'+k;if($(id))$(id).value=x[k.charAt(0).toLowerCase()+k.slice(1)]||''});$('#settingAvailability').checked=!!x.availability;$('#settingHeroLeadText').value=x.heroLeadText||'I DESIGN';$('#settingHeroTypewriterPhrases').value=Array.isArray(x.heroTypewriterPhrases)?x.heroTypewriterPhrases.join('\n'):'BRANDS THAT SELL.';updateHeroCopyPreview();updateSiteSeoPreview();const heroPreview=$('#heroImagePreview');if(heroPreview&&x.heroImage)heroPreview.innerHTML=`<img src="${esc(x.heroImage)}" alt="Hero preview">`;renderTestimonials(t.testimonials||[]);$('#inquiryList').innerHTML=(iq.inquiries||[]).map(x=>`<div class="project-item"><div><strong>${esc(x.name)} · ${esc(x.service||'General')}</strong><small>${esc(x.email)} · ${esc(x.status)} · ${new Date(x.createdAt).toLocaleString()}<br>${esc(x.message)}</small></div><select class="inquiry-status" data-id="${esc(x.id)}"><option ${x.status==='NEW'?'selected':''}>NEW</option><option ${x.status==='CONTACTED'?'selected':''}>CONTACTED</option><option ${x.status==='CLOSED'?'selected':''}>CLOSED</option></select></div>`).join('')||'<p class="notice">No inquiries yet.</p>';$$('.inquiry-status').forEach(sel=>sel.addEventListener('change',async()=>{await api('/admin/maintenance/inquiries/'+sel.dataset.id,{method:'PATCH',body:JSON.stringify({status:sel.value})});loadMaintenance()}));$('#activityList').innerHTML=(a.activity||[]).map(x=>`<div class="project-item"><div><strong>${esc(x.action)}</strong><small>${esc(x.entity)} · ${esc(x.label||'')} · ${new Date(x.createdAt).toLocaleString()}</small></div></div>`).join('')||'<p class="notice">No activity yet.</p>';$('#reviewList').innerHTML=(rv.reviews||[]).map(x=>`<div class="project-item"><div><strong>${esc(x.decision)}</strong><small>${esc(x.clientName)}${x.clientEmail?' · '+esc(x.clientEmail):''} · ${new Date(x.createdAt).toLocaleString()}<br>${esc(x.comment||'No comment')}</small></div></div>`).join('')||'<p class="notice">No client reviews yet.</p>'}catch(e){$('#maintenanceMsg').textContent=e.message}}

