function renderSkills(items){const el=$('#skillsList');if(!el)return;el.innerHTML=(items||[]).slice().sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0)).map(x=>`<div class="project-item skill-admin-item"><img src="${esc(x.icon||'')}" alt="" onerror="this.style.visibility='hidden'"><div><strong>${esc(x.name)}</strong><small>${esc(x.category)} · ${esc(x.level||'')} · ${x.visible?'VISIBLE':'HIDDEN'}${x.featured?' · FEATURED':''}<br>${esc(x.description||'')}</small></div><div class="item-actions"><button type="button" class="admin-btn js-skill-edit" data-id="${esc(x.id||'')}">EDIT</button><button type="button" class="admin-btn danger js-skill-delete" data-id="${esc(x.id||'')}">DELETE</button></div></div>`).join('')||'<p class="notice">No tools added yet.</p>';el.querySelectorAll('.js-skill-edit').forEach(b=>b.onclick=()=>{const x=(items||[]).find(v=>v.id===b.dataset.id);if(!x)return;$('#skillId').value=x.id||'';$('#skillName').value=x.name||'';$('#skillCategory').value=x.category||'Creative / Design';$('#skillIcon').value=x.icon||'';$('#skillLevel').value=x.level||'';$('#skillDescription').value=x.description||'';$('#skillOrder').value=x.sortOrder||0;$('#skillVisible').checked=x.visible!==false;$('#skillFeatured').checked=x.featured!==false;document.querySelector('#maintenanceSkills .panel')?.scrollIntoView({behavior:'smooth',block:'start'})});el.querySelectorAll('.js-skill-delete').forEach(b=>b.onclick=async()=>{const x=(items||[]).filter(v=>v.id!==b.dataset.id);await saveSkills(x);});}
async function getSkills(){const d=await api('/admin/maintenance/settings');return Array.isArray(d.settings?.skillsConfig)?d.settings.skillsConfig:[]}
async function saveSkills(skills){await api('/admin/maintenance/settings',{method:'PATCH',body:JSON.stringify({skillsConfig:skills})});msg($('#skillsMsg'),'Skills saved.',true);loadMaintenance()}

function renderTestimonials(items){const el=$('#testimonialList');el.innerHTML=items.map(x=>`<div class="project-item"><div><strong>${esc(x.client)}</strong><small>${esc(x.company||'')} · ${x.published?'PUBLISHED':'HIDDEN'}${x.featured?' · FEATURED':''}</small></div><div><button type="button" class="admin-btn js-test-edit" data-id="${esc(x.id)}">EDIT</button><button type="button" class="admin-btn danger js-test-delete" data-id="${esc(x.id)}">DELETE</button></div></div>`).join('')||'<p class="notice">No testimonials yet.</p>';el.querySelectorAll('.js-test-edit').forEach(b=>b.addEventListener('click',async()=>{const x=(await api('/admin/maintenance/testimonials')).testimonials.find(v=>v.id===b.dataset.id);if(!x)return;$('#testimonialId').value=x.id;$('#testimonialClient').value=x.client;$('#testimonialCompany').value=x.company||'';$('#testimonialRole').value=x.role||'';$('#testimonialQuote').value=x.quote;$('#testimonialPhoto').value=x.photo||'';$('#testimonialProjectId').value=x.projectId||'';$('#testimonialFeatured').checked=x.featured;$('#testimonialPublished').checked=x.published;$('#testimonialOrder').value=x.sortOrder||0}));el.querySelectorAll('.js-test-delete').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete testimonial?'))return;await api('/admin/maintenance/testimonials/'+b.dataset.id,{method:'DELETE'});loadMaintenance()}))}
$('#skillsForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const items=await getSkills();const id=$('#skillId').value||('skill-'+Date.now());const item={id,name:$('#skillName').value.trim(),category:$('#skillCategory').value,icon:$('#skillIcon').value.trim()||null,level:$('#skillLevel').value.trim()||null,description:$('#skillDescription').value.trim()||null,sortOrder:Number($('#skillOrder').value||0),visible:$('#skillVisible').checked,featured:$('#skillFeatured').checked};const next=[...items.filter(x=>x.id!==id),item];await saveSkills(next);e.target.reset();$('#skillId').value='';$('#skillVisible').checked=true;$('#skillFeatured').checked=true}catch(e){msg($('#skillsMsg'),e.message)}});
$('#clearSkill')?.addEventListener('click',()=>{$('#skillsForm')?.reset();$('#skillId').value='';$('#skillVisible').checked=true;$('#skillFeatured').checked=true});
$('#seedSkills')?.addEventListener('click',async()=>{const current=await getSkills();const merged=[...current];for(const item of STARTER_SKILLS){if(!merged.some(x=>x.id===item.id))merged.push(item)}await saveSkills(merged);});function updateHeroCopyPreview(){const lead=$('#settingHeroLeadText')?.value.trim()||'I DESIGN';const raw=$('#settingHeroTypewriterPhrases')?.value||'';const phrases=raw.split(/\n+/).map(v=>v.trim()).filter(Boolean).slice(0,12);if($('#heroCopyPreviewLead'))$('#heroCopyPreviewLead').textContent=lead;if($('#heroCopyPreviewPhrase'))$('#heroCopyPreviewPhrase').textContent=phrases[0]||'BRANDS THAT SELL.';if($('#heroLeadCount'))$('#heroLeadCount').textContent=lead.length;if($('#heroPhraseCount'))$('#heroPhraseCount').textContent=phrases.length}
$('#settingHeroLeadText')?.addEventListener('input',updateHeroCopyPreview);
$('#settingHeroTypewriterPhrases')?.addEventListener('input',updateHeroCopyPreview);
$('#settingsForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const data={siteName:$('#settingSiteName').value,title:$('#settingTitle').value,email:$('#settingEmail').value||null,inquiryRecipientEmail:$('#settingInquiryRecipientEmail').value||null,inquirySubject:$('#settingInquirySubject').value||null,phone:$('#settingPhone').value||null,location:$('#settingLocation').value||null,availability:$('#settingAvailability').checked,availabilityLabel:$('#settingAvailabilityLabel').value||null,linkedin:$('#settingLinkedin').value||null,behance:$('#settingBehance').value||null,dribbble:$('#settingDribbble').value||null,instagram:$('#settingInstagram').value||null,github:$('#settingGithub').value||null,metaTitle:$('#settingMetaTitle').value||null,metaDescription:$('#settingMetaDescription').value||null,ogImage:$('#settingOgImage').value||null,heroImage:$('#settingHeroImage').value||null,heroLeadText:$('#settingHeroLeadText').value.trim()||'I DESIGN',heroTypewriterPhrases:$('#settingHeroTypewriterPhrases').value.split(/\n+/).map(v=>v.trim()).filter(Boolean).slice(0,12).length?$('#settingHeroTypewriterPhrases').value.split(/\n+/).map(v=>v.trim()).filter(Boolean).slice(0,12):['BRANDS THAT SELL.']};await api('/admin/maintenance/settings',{method:'PATCH',body:JSON.stringify(data)});msg($('#settingsMsg'),'Settings saved.',true);loadMaintenance()}catch(e){msg($('#settingsMsg'),e.message)}});
$('#sliderSettingsForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const sliderConfig=readSliderSettings();await api('/admin/maintenance/settings',{method:'PATCH',body:JSON.stringify({sliderConfig})});msg($('#sliderSettingsMsg'),'Slider settings saved. Refresh the public site to apply.',true);fillSliderSettings(sliderConfig)}catch(e){msg($('#sliderSettingsMsg'),e.message)}});
$('#resetSliderSettings')?.addEventListener('click',()=>{fillSliderSettings(DEFAULT_SLIDER_SETTINGS);msg($('#sliderSettingsMsg'),'Defaults loaded. Click SAVE to apply.',true)});
$('#previewSliderSettings')?.addEventListener('click',()=>window.open('/#special','_blank'));
$$('.maintenance-subtab').forEach(b=>b.addEventListener('click',()=>switchMaintenancePanel(b.dataset.maintenanceTab)));
$$('#maintenanceBackground input[type=range]').forEach(el=>el.addEventListener('input',updateParticleValueLabels));$('#backgroundSettingsForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const particleConfig=readParticleSettings();currentParticleConfig=particleConfig;const existing=(await api('/admin/maintenance/settings')).settings?.sliderConfig||{};await api('/admin/maintenance/settings',{method:'PATCH',body:JSON.stringify({sliderConfig:{...existing,particleConfig}})});msg($('#backgroundSettingsMsg'),'Background settings saved. Refresh the public site to apply.',true);fillParticleSettings(particleConfig)}catch(err){msg($('#backgroundSettingsMsg'),err.message)}});$('#particleReset')?.addEventListener('click',()=>fillParticleSettings(DEFAULT_PARTICLE_CONFIG));
$('#testimonialForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const data={client:$('#testimonialClient').value,company:$('#testimonialCompany').value||null,role:$('#testimonialRole').value||null,quote:$('#testimonialQuote').value,photo:$('#testimonialPhoto').value||null,projectId:$('#testimonialProjectId').value||null,featured:$('#testimonialFeatured').checked,published:$('#testimonialPublished').checked,sortOrder:Number($('#testimonialOrder').value||0)};const id=$('#testimonialId').value;if(id)await api('/admin/maintenance/testimonials/'+id,{method:'PATCH',body:JSON.stringify(data)});else await api('/admin/maintenance/testimonials',{method:'POST',body:JSON.stringify(data)});e.target.reset();$('#testimonialId').value='';$('#testimonialPublished').checked=true;msg($('#testimonialMsg'),'Testimonial saved.',true);loadMaintenance()}catch(e){msg($('#testimonialMsg'),e.message)}});
$('#refreshStatus')?.addEventListener('click',loadMaintenance);
$('#restoreBackup')?.addEventListener('click',async()=>{const f=$('#backupFile').files[0];if(!f){alert('Choose a backup JSON first.');return}const mode=$('#restoreMode').value;if(mode==='REPLACE'&&!confirm('REPLACE will delete current CMS records before restoring. Continue?'))return;try{const body=JSON.parse(await f.text());const r=await fetch('/api/admin/maintenance/restore?mode='+encodeURIComponent(mode),{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Restore failed');msg($('#maintenanceMsg'),'Backup restored successfully.',true);await load();await loadMaintenance()}catch(e){msg($('#maintenanceMsg'),e.message)}});
$('#projectSearch')?.addEventListener('input',renderProjects);$('#contentSearch')?.addEventListener('input',renderContent);$('#dashboardRefresh')?.addEventListener('click',()=>loadDashboard());$$('[data-quick]').forEach(b=>b.addEventListener('click',()=>{const x=b.dataset.quick;if(x==='new-project'){openAdminTab('projects');$('#clearProject')?.click();$('#title')?.focus()}else if(x==='new-content'){openAdminTab('content');$('#clearContent')?.click();$('#contentTitle')?.focus()}else if(x==='inquiries'){openAdminTab('maintenance');setTimeout(()=>switchMaintenancePanel('inquiries'),0)}else if(x==='settings'){openAdminTab('maintenance');setTimeout(()=>switchMaintenancePanel('site'),0)}}));
$('#year').value=new Date().getFullYear();$('#sortOrder').value=0;$('#sliderEnabled').checked=true;$('#sliderTransition').value='AUTO';$('#contentStatus')&&($('#contentStatus').value='DRAFT');renderGallery();updateProjectSeoPreview();updateContentSeoPreview();updateSiteSeoPreview();boot();openAdminTab('dashboard');
